// Producent (np. z MassTransit – popularna biblioteka .NET nad brokerami)
public class OrdersController(IPublishEndpoint bus, ShopDb db) : ControllerBase
{
    [HttpPost("/api/orders")]
    public async Task<IActionResult> Place(PlaceOrder cmd, CancellationToken ct)
    {
        var order = Order.Create(cmd);
        db.Orders.Add(order);
        await db.SaveChangesAsync(ct);
        await bus.Publish(new OrderPlaced(order.Id, order.Total), ct);
        return Accepted(new { order.Id });
    }
}

// Konsument
public class SendConfirmation(IEmailSender email) : IConsumer<OrderPlaced>
{
    public Task Consume(ConsumeContext<OrderPlaced> ctx) =>
        email.SendAsync(ctx.Message.OrderId, ctx.CancellationToken);
}

public async Task Consume(ConsumeContext<OrderPaid> ctx)
{
    var msgId = ctx.MessageId!.Value;
    if (await db.ProcessedMessages.AnyAsync(m => m.Id == msgId))
        return;                                   // już było – pomijamy

    var order = await db.Orders.FindAsync(ctx.Message.OrderId);
    order!.MarkAsPaid();                          // "ustaw", nie "dodaj"
    db.ProcessedMessages.Add(new ProcessedMessage(msgId));
    await db.SaveChangesAsync();                  // jedna transakcja
}

